with latest as (select * from (select *, row_number() over (partition by dept_id order by hire_date desc nulls last, id) as rank_in_group from employees) t where rank_in_group = 1) select s.id, s.email, s.dept_id, s.manager_id, s.job_title, s.salary, s.level, (select max(x.salary) from employees x where x.manager_id = s.manager_id) as max_employee_salary from latest s order by manager_id desc nulls first;
